fn slurp::(path) {
    return @mem_from_bytes(@read_text(path));
}

fn slurp_and_unlink::(path) {
    let m = slurp(path);
    @remove(path);
    return m;
}

fn wipe::(m) {
    @mem_secure_wipe(m);
    @free(m);
    return null;
}

fn exec_source::(m) {
    @exec(@mem_to_string(m));
    return null;
}

fn run_zminus::(path) {
    let m = slurp_and_unlink(path);
    exec_source(m);
    wipe(m);
    return null;
}

fn spawn_elf::(m, argv) {
    if (@platform() != "linux") { @raise("spawn_elf: linux only"); }
    let libc = @dlopen("libc.so.6");
    let n = @len(argv);
    let size = @mem_size(m);
    let ptrs = [];
    for i in @range(0, n) {
        let s = @str(argv[i]);
        let buf = @calloc(1, @len(s) + 1);
        @mem_load_str(buf, 0, s);
        @push(ptrs, @ptr_addr(@ptr(buf)));
    }
    let argvMem = @calloc(n + 1, 8);
    for i in @range(0, n) {
        @mem_write_u64(argvMem, i * 8, ptrs[i]);
    }
    @mem_write_u64(argvMem, n * 8, 0);
    let argvPtr = @ptr_addr(@ptr(argvMem));
    let namePtr = ptrs[0];
    let fd = @ffi_i64(libc, "memfd_create", namePtr, 0);
    if (fd < 0) { @raise("memfd_create failed"); }
    let bufPtr = @ptr_addr(@ptr(m));
    let written = @ffi_i64(libc, "write", fd, bufPtr, size);
    if (written != size) { @raise("short write to memfd"); }
    @ffi_i64(libc, "fexecve", fd, argvPtr, 0);
    @raise("fexecve returned");
    return null;
}

fn run_elf::(path, argv) {
    let m = slurp_and_unlink(path);
    spawn_elf(m, argv);
    wipe(m);
    return null;
}
